--
-- Table structure for table `knowledge_point_relation`
--

DROP TABLE IF EXISTS `knowledge_point_relation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `knowledge_point_relation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '关联ID',
  `source_id` bigint NOT NULL COMMENT '源知识点ID',
  `target_id` bigint NOT NULL COMMENT '目标知识点ID',
  `relation_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT 'prerequisite' COMMENT '关联类型（prerequisite-前置依赖 related-相关参考 extension-扩展延伸）',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '关联描述',
  `weight` int DEFAULT '1' COMMENT '关联权重/强度（用于拓扑图连线粗细）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_source_target` (`source_id`,`target_id`) USING BTREE,
  KEY `idx_source_id` (`source_id`) USING BTREE,
  KEY `idx_target_id` (`target_id`) USING BTREE,
  CONSTRAINT `fk_kpr_source` FOREIGN KEY (`source_id`) REFERENCES `knowledge_point` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_kpr_target` FOREIGN KEY (`target_id`) REFERENCES `knowledge_point` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=11384 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='知识点关联表（拓扑图边）';
/*!40101 SET character_set_client = @saved_cs_client */;

