CREATE TABLE `position` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '岗位ID',
  `name` varchar(200) NOT NULL COMMENT '岗位名称',
  `description` varchar(1000) DEFAULT NULL COMMENT '岗位描述',
  `status` char(1) DEFAULT '0' COMMENT '状态（0正常 1停用）',
